const item = $input.first().json;
const jobId = item.jobId;
if (!jobId) throw new Error('Missing jobId for full text pipeline');
const apiToken = $env.FAIRYTELLER_API_TOKEN;
if (!apiToken) throw new Error('FAIRYTELLER_API_TOKEN is not configured');
const jobUrl = 'https://fairyteller.ru/api/fairyteller/jobs/' + jobId;

function cleanError(error) {
  const body = error?.response?.body || error?.cause?.response?.body;
  const message = typeof body === 'string'
    ? body
    : body?.error?.message || body?.message || error?.message || 'unknown error';
  return String(message).replace(/\s+/g, ' ').trim().slice(0, 500);
}

async function request(options) {
  return await this.helpers.httpRequest({
    ...options,
    headers: {
      Authorization: 'Bearer ' + apiToken,
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    json: true,
    timeout: options.timeout || 30000,
  });
}

let current = null;
try {
  current = await request.call(this, { method: 'GET', url: jobUrl });
} catch (error) {
  console.log('Could not read current job before full text claim: ' + cleanError(error));
}

const currentFullText = current?.artifacts?.fullText || {};
const currentFullTextStatus = String(currentFullText.status || '').toLowerCase();
const alreadyClaimed = currentFullTextStatus === 'generating' && Boolean(currentFullText.startedAt || currentFullText.trigger);
if (currentFullTextStatus === 'ready' || alreadyClaimed) {
  console.log('Full text already ' + currentFullTextStatus + ' for ' + jobId + '; skipping duplicate launch');
  return [];
}

const startedAt = new Date().toISOString();
const progress = Math.max(45, Number(current?.progress || item.progress || 35) || 45);
const trigger = item.pipeline?.fullTextFallback ? 'visuals_fallback' : 'text_fanout';

await request.call(this, {
  method: 'PATCH',
  url: jobUrl,
  body: {
    stage: 'text',
    progress,
    message: 'Пишем продолжение истории',
    artifacts: {
      fullText: { status: 'generating', startedAt, trigger },
    },
  },
});

return [{ json: { ...item, fullTextClaim: { status: 'generating', startedAt, trigger } } }];

const item = $input.first().json;
const order = item.order || {};
const text = item.text || {};
const bible = text.bible || {};
const firstChapter = text.chapters?.[0] || {};
const chapterTextBlockTargets = text.chapterTextBlockTargets || { 1: 4, 2: 4, 3: 6, 4: 6, 5: 5 };
const chaptersTarget = Math.max(1, Math.min(8, Number(order.chapters || bible.chapterPlan?.length || 5)));
const laterNumbers = Array.from({ length: Math.max(0, chaptersTarget - 1) }, (_, index) => index + 2);
const chapterPlan = Array.isArray(bible.chapterPlan) ? bible.chapterPlan : [];
const laterPlan = laterNumbers.map((n) => {
  const planned = chapterPlan.find((chapter) => Number(chapter.n) === n) || { n, title: 'Глава ' + n, beat: '' };
  return { n, title: planned.title || ('Глава ' + n), beat: planned.beat || planned.summary || '', textBlockTarget: chapterTextBlockTargets[n] || 5 };
});
const activeHeroes = (order.heroes || []).filter((hero) => hero.name || hero.description || hero.relation || hero.hasPhoto);
const heroCount = activeHeroes.length;
const hasChildHero = activeHeroes.some((hero) => hero.ageGroup === 'child');
const childTonePolicy = hasChildHero
  ? 'ОБЯЗАТЕЛЬНЫЙ ПРИОРИТЕТ: среди героев есть ребенок. Вся история должна оставаться светлой, жизнеутверждающей и эмоционально безопасной. Допустимы загадка, волнение и преодолимые препятствия, но запрещены смерть, жестокость, пытки, безысходность, предательство близких, травмирующее преследование, хоррор и глобальная катастрофа. После напряжения давай передышку, поддержку или юмор; финал теплый, завершенный и обнадеживающий. Это правило важнее жанровой атмосферы.'
  : 'Сохраняй человеческое тепло, эмоциональные передышки и завершенный обнадеживающий финал.';
const protagonistMode = heroCount <= 1 ? 'solo' : (heroCount === 2 ? 'duo' : 'ensemble');
function protagonistPolicyFor(mode) {
  if (mode === 'solo') return 'SOLO: продолжай историю как книгу об одном главном герое. Не добавляй второго постоянного героя, напарника, романтического партнера или co-hero. Эпизодические встречные персонажи допустимы, но они не проходят весь сюжет и не получают равную арку.';
  if (mode === 'duo') return 'DUO: держи фокус на двух заданных героях. Не добавляй третьего постоянного спутника.';
  return 'ENSEMBLE: держи фокус только на заданных пользователем героях. Не добавляй новых постоянных участников команды.';
}
function publicWorldTitle(value) {
  const aliases = {
